import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix='', env=os.environ):
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(tomllib.load(f))
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            config[env_key] = _coerce_value(value, defaults.get(env_key))
    return config

def _coerce_value(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ['true', '1', 'yes']
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for {value}')

import pytest
from envcfg import load_config, ConfigError

def test_load_defaults():
    defaults = {'key': 'value'}
    config = load_config(defaults)
    assert config == {'key': 'value'}

def test_load_toml():
    defaults = {'key': 'value'}
    config = load_config(defaults, toml_path='config.toml')
    assert config == {'key': 'toml_value'}

def test_load_env():
    defaults = {'key': 'value'}
    os.environ['APP__KEY'] = 'env_value'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'key': 'env_value'}

def test_coerce_int():
    defaults = {'key': 123}
    os.environ['APP__KEY'] = '456'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'key': 456}

def test_coerce_float():
    defaults = {'key': 123.45}
    os.environ['APP__KEY'] = '67.89'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'key': 67.89}

def test_coerce_bool():
    defaults = {'key': True}
    os.environ['APP__KEY'] = 'false'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'key': False}

def test_coerce_str():
    defaults = {'key': 'value'}
    os.environ['APP__KEY'] = 'new_value'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'key': 'new_value'}

def test_missing_default():
    defaults = {'key': 'value'}
    os.environ['APP__MISSING'] = 'value'
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__')

